                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
  CREATE OR REPLACE FORCE EDITIONABLE VIEW "MPF_USER_DEPT_MAIN_ASSO_V" ("EXT_USER_ID", "GENDER", "HIRED_DATE", "LEADER_EXT_USER_ID", "LEADER_SYNC_USER_ID", "LEADER_EXT_USER_NAME", "CREATED_BY", "CREATION_DATE", "UPDATED_BY", "UPDATE_DATE", "REMARK", "JOB_NUMBER", "TENANT_ID", "SYNC_USER_ID", "UNIONID", "TITLE", "NAME", "AVATAR", "STATE_CODE", "MOBILE", "EMAIL", "JOB_LEVEL_CODE", "JOB_LEVEL", "EXT_ORG_ID", "RELATED_TYPE", "IS_MAIN_ORG", "EXT_ORG_NAME", "PARENT_ID", "LAST_LOGIN_DATE", "PASSWORD", "IS_MAIN_WORKER", "BASE_DEPT_ID") AS     
  SELECT UO.USER_ID                                      AS EXT_USER_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       UP.GENDER,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       UO.HIRED_DATE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
       uo.LEADER_USER_ID                               AS LEADER_EXT_USER_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
       uo.LEADER_EXTRA_USER_ID                         AS LEADER_SYNC_USER_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
       UO.LEADER_USER_NAME                             AS LEADER_EXT_USER_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
       UP.CREATED_BY                                   AS CREATED_BY,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
       UP.CREATION_DATE                                AS CREATION_DATE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       UP.UPDATED_BY                                   AS UPDATED_BY,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
       UP.UPDATE_DATE                                  AS UPDATE_DATE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       UP.REMARK                                       AS REMARK,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       UO.JOB_NUMBER,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
       UO.TENANT_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       UO.EXTRA_USER_ID                                AS SYNC_USER_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       UO.UNION_ID                                     AS UNIONID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
       UO.TITLE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
       UO.NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
       UO.AVATAR,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       UO.STATE_CODE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
       UO.MOBILE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       UO.EMAIL,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
       NVL(UDP.JOB_LEVEL_CODE, 50)                     as JOB_LEVEL_CODE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
       NVL(UDP.JOB_LEVEL, 'KEY_STAFF')                 as JOB_LEVEL,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       UO.DEPT_ID                                      AS EXT_ORG_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
       decode(UO.MAIN_DEPT_ORDER, 0, 'MAIN', 'EXTRA')  AS RELATED_TYPE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       decode(UO.MAIN_DEPT_ORDER, 0, 1, 0)             AS IS_MAIN_ORG,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       NVL(SELECT_DEPT_NAME(UO.DEPT_ID), UO.DEPT_NAME) AS EXT_ORG_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       0                                               AS PARENT_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       UP.LAST_LOGIN_DATE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
       UP.PASSWORD,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
       NVL(UP.IS_MAIN_WORKER, 0)                       AS IS_MAIN_WORKER,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
       UO.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
FROM MPF_SHARE_BASIC_USER_INFO_V UO                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
         LEFT JOIN BAO_USER_EXPAND UP ON UP.USER_ID = UO.USER_ID AND UP.BASE_DEPT_ID = UO.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
         LEFT JOIN BAO_USER_DEPT_EXPAND UDP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                   ON UDP.USER_ID = UO.USER_ID and UDP.DEPT_ID = UO.DEPT_ID AND UDP.BASE_DEPT_ID = UO.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
where uo.IS_LEAVE = 0                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
  and UO.MAIN_DEPT_ORDER = 0                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
  and UO.TENANT_ID = 3                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 and exists(select 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
             from JING_JIE.SHARE_AUTH_USER_ACCOUNT_OPS_V aa                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
             where aa.USER_ID = UO.USER_ID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
               and aa.APP_CODE = 'JING_BAO'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
               and aa.OPS_BASE_DEPT_ID = UO.BASE_DEPT_ID);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              

